For some absolute constant $c>0$,
\begin{equation*}
\sum_{n\leqslant x} \frac 1n \lambda(n) \lambda(n+1) \ll (\log x)^{1-c}.
\end{equation*}

Let $\varepsilon_1>0$ be a sufficiently small absolute constant. Let $H>0$ be sufficiently large in terms of $\varepsilon_1$. Let $J$ be a positive integer with $J \leqslant \varepsilon_1^2 \log \log H$, and let $H_0 = \exp \big((\log H)^{1-\varepsilon_1}\big)$.

Let $C := \exp\big(\varepsilon_1 (\log \log H)/(2J)\big)$. For $1\leqslant i\leqslant J$, let $\mathcal{P}_i$ be the set of all primes $p$ with
\begin{equation*}
C^{2i-2} < \frac{\log p}{\log H_0} < C^{2i-1}
\end{equation*}
and let $V_i := \sum_{p\in \mathcal{P}_i} \frac{1}{p}$.

Let $N$ be an integer such that $\log N \geqslant (\log H)^3$. Then
\begin{equation}

	\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}}\,  \sum_{\substack{n\in (N, 2N] \\ p_1\cdots p_{J} \mid n}}\lambda(n) \lambda(n+p_1\cdots p_{J}) \ll (V_1\cdots V_{J})^{3/4} N.
\end{equation}

Let $\varepsilon_1$, $H$, $J$, $H_0$, $(\mathcal{P}_i)$ and $(V_i)$ be as in 2.1. Let $V := \max_i V_i$. 

Let $N \geqslant \exp\big((\log H)^{2}\big)$. With $S_1$ and $S_2$ as in 9 and 16, we have
\begin{equation*}
\left| S_1 - S_2 \right| \ll \frac{N}{(\log H)^{1/2500}}.
\end{equation*}

There exists a weighted graph $G = (I_N, w)$ with $\left\|w\right\|_{\infty} \leqslant 1$ such that
\begin{enumerate}
	\item (close to $G_0$) $\left\|w-w_0\right\|_1 \ll N$;
	\item (localised near the diagonal) $w(m,n) = 0$ whenever $|m-n| > H$;
	\item (small trace) $\mathrm{Tr}\big((\mathrm{Ad}_{G})^{K}\big) \leqslant \big( e^{O(J)} V^{2J/3}\big)^{K} N$, where $K = 2\lfloor \log H\rfloor$.
\end{enumerate}
Here $\left\|f\right\|_1 := \sum_{m,n}|f(m,n)|$ for $f:I_N\times I_N \to \mathbb{C}$.

Let $A  = (a_{m, n})_{m, n\in I_N}$ be a Hermitian matrix such that $a_{m,n} = 0$ whenever $|m-n| > H$. Let $\alpha>0$, $\varepsilon\in (0,1)$, and suppose that $N \geqslant 10H/\varepsilon^2$. Then at least one of the following holds.
\begin{enumerate}
	\item There is a subset $E\subset I_N$ with $|E| \ll \varepsilon N$ such that every eigenvalue of $A|_{I_N\setminus E}$ has absolute value~$\leqslant \alpha$.
	\item For any even integer $R\geqslant 2$, 
	\begin{equation*}
		\mathrm{Tr} \big(A^{R}\big) \geqslant \frac{\varepsilon^2}{H} \alpha^{R}N.
	\end{equation*}
\end{enumerate}

Let $1\leqslant R\leqslant K$. Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $[\![R]\!]\times [\![J]\!] = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$. We have
\begin{equation*}
	\sum_{\substack{\boldsymbol{d} \in \mathbf{P}_{\!R}}} \, \prod_{p\mid \rho_{\boldsymbol{d}}} \frac{1}{p} \ll e^{O(KJ)}V^{|\mathcal{S}|+(\left|\mathcal{L}\right|+\left|\mathcal{U}\right|)/2}.
\end{equation*}

Let $1\leqslant R\leqslant K$. Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $[\![R]\!]\times [\![J]\!] = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$ and $|\mathcal{U}| \leqslant K^{2\varepsilon_1}$. We have
\begin{equation*}
 \sum_{\substack{\boldsymbol{d}\in \mathbf{U}_{\!R}}}\,\prod_{p\mid \rho_{\boldsymbol{d}}}\, \frac{1}{p} \ll 1.
\end{equation*}

Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $[\![K]\!]\times[\![J]\!] = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$ and $|\mathcal{U}| \leqslant K^{2\varepsilon_1}$. Let $0\leqslant R \leqslant K$ and let $\boldsymbol{d}'\in (\pm \mathcal{D})^{R}$.

Then
\begin{equation*}
	\sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}\\ \widetilde{\boldsymbol{d}} = \boldsymbol{d}'}}\, \prod_{\substack{p\mid \rho_{\boldsymbol{d}} \\ p\nmid \rho_{\boldsymbol{d}'}}} \frac{1}{p} \ll e^{O(KJ)} V^{(K-R)J/2},
\end{equation*}
where $\widetilde{\boldsymbol{d}}$ is the reduced vector associated to $\boldsymbol{d}$ (see 6.11).

Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $[\![K]\!]\times[\![J]\!] = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$. Let $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}$. Assume that
\begin{equation*}
\big|{\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})}\big| \leqslant K^{1/2}.
\end{equation*}
Let $R$ be an arithmetic progression whose modulus $q_{R}$ is a square-free product of primes in $\mathcal{P}$. We assume that $q_{R}$ is divisible by at most $K^{1-\varepsilon_1}$ primes $p\mid \rho_{\boldsymbol{d}; \mathcal{S}}$. 

Let
\begin{equation*}
E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R) := \mathbb{E} \left[\,\mathbf{1}_{\mathbf{n}\in R}\, \prod_{i\in [\![K]\!]} W\big(\omega_{\mathcal{P}}(\mathbf{n}+b_i)\big)\prod_{(i,j)\in \mathcal{S}} \left(\mathbf{1}_{d_{ij}\mid \mathbf{n} + b_i} - \frac{1}{d_{ij}}\right) \mathbf{1}_{\substack{d_{ij}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ d_{ij}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right].
\end{equation*}
Then
\begin{equation*}
E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R) \ll e^{O(K J)} V^{-|\mathcal{S}|/2}  \prod_{p\mid q_{R} \rho_{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}}\frac{1}{p}.
\end{equation*}

Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $[\![K]\!]\times[\![J]\!] = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$. For every $\boldsymbol{d} \in \mathbf{D}^{\mathcal{S}}_{\!K}$, there exists a function 
\begin{equation*}
	\mathrm{rank}_{\boldsymbol{d}} : (\mathcal{Y}-\boldsymbol{b})^{\cap} \to \mathbb{Z}^{\geqslant 0} \cup \{+\infty\}
\end{equation*}
satisfying the following properties. 

Define the arithmetic progression $A_{\boldsymbol{d}} := \{n\in \mathbb{Z} : \forall (i,j)\in \mathcal{L}, \ d_{ij} \mid n+b_i\}$. 

Let~$X_{\boldsymbol{d}}$ be the set of all $R\in (\mathcal{Y}-\boldsymbol{b})^{\cap}$ such that ${\mathrm{rank}_{\boldsymbol{d}}(R) < K^{5\varepsilon_1}}$. Let $\partial X_{\boldsymbol{d}}$ be the set of all $R\in (\mathcal{Y}-\boldsymbol{b})^{\cap}\setminus X_{\boldsymbol{d}}$ of the form $R = R'\cap P$ for some $R'\in X_{\boldsymbol{d}}$ and $P\in \mathcal{Y}-\boldsymbol{b}$.
\begin{enumerate}
	\item  (Primes dividing the modulus) For every $R\in (\mathcal{Y}-\boldsymbol{b})^{\cap}$, 
	\begin{equation*}
		\omega(q_{R}) \leqslant L J \, \mathrm{rank}_{\boldsymbol{d}}(R) + K J.
	\end{equation*}
	\item  (Primes $p\mid \rho_{\boldsymbol{d}; \mathcal{S}}$ dividing the modulus) For every $R\in (\mathcal{Y}-\boldsymbol{b})^{\cap}$, 
	\begin{equation*}
		\left| \{p: p\mid q_{R},\, p\mid \rho_{\boldsymbol{d}; \mathcal{S}}\}\right|\leqslant L J \, \mathrm{rank}_{\boldsymbol{d}}(R).
	\end{equation*}
	\item  (Combinatorial sieve) Let $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}$. For all $n\in \mathbb{Z}$, we have 
	\begin{equation*}
		\mathbf{1}_{\substack{\forall i,\,n+b_i \in Y_{\!L} \, \mathrm{ and }\, n\in A_{\boldsymbol{d}}}}  = \sum_{\substack{R\in X_{\boldsymbol{d}}}} c_{R,\boldsymbol{d}}  \mathbf{1}_{n\in R\cap A_{\boldsymbol{d}}}\,  +\,  O\Bigg(  3^{3K J}  \!\!\!\! \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}} \!\!\!\! \mathbf{1}_{n\in R\cap A_{\boldsymbol{d}}} \Bigg),
	\end{equation*}
	where the coefficients $c_{R,\boldsymbol{d}}$ are independent of $n$ and satisfy $|c_{R,\boldsymbol{d}}| \leqslant 2^{2K J}$.
	\item  (Main term bound) We have
        \begin{equation*}
        		\sum_{\substack{R\in X_{\boldsymbol{d}}}} \prod_{\substack{p\mid q_{R}\\ p\nmid \rho_{\boldsymbol{d}}}}\frac{1}{p} \ll e^{O(K J)}.
        \end{equation*}
	\item  (Remainder term bound) Suppose $|\mathcal{U}| \leqslant K^{2\varepsilon_1}$. Then
	\begin{equation*}
	 \sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}}} \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}}\, \prod_{\substack{p\mid q_{R} \rho_{\boldsymbol{d}}}}\frac{1}{p} \ll 1.
	 \end{equation*}
\end{enumerate}
